CREATE TABLE framework_versions (framework_version_id BIGSERIAL PRIMARY KEY, version TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('DRAFT','FROZEN','SUPERSEDED')), effective_at TIMESTAMPTZ NOT NULL, scoring_config JSONB NOT NULL, rules_config JSONB NOT NULL, source_spec_document_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ipos (ipo_id BIGSERIAL PRIMARY KEY, company_name TEXT NOT NULL, segment TEXT NOT NULL CHECK (segment IN ('MAINBOARD','SME')), exchange TEXT, issue_open_date DATE, issue_close_date DATE, listing_date DATE, price_band_low NUMERIC(14,2), price_band_high NUMERIC(14,2), issue_price NUMERIC(14,2), issue_size NUMERIC(18,2), status TEXT NOT NULL DEFAULT 'DISCOVERED' CHECK (status IN ('DISCOVERED','UPCOMING','OPEN','CLOSED','AWAITING_LISTING','LISTED','WITHDRAWN','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (company_name, issue_open_date));
CREATE TABLE checkpoints (checkpoint_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL REFERENCES ipos(ipo_id) ON DELETE RESTRICT, checkpoint_type TEXT NOT NULL CHECK (checkpoint_type IN ('T1_DISCOVERY','INTERMEDIATE','T2_FINAL_DAY')), checkpoint_time TIMESTAMPTZ NOT NULL, score NUMERIC(6,2) CHECK (score >= 0 AND score <= 100), grade TEXT NOT NULL CHECK (grade IN ('A++','A+','A','REJECT','NV')), decision TEXT NOT NULL, bear_gain_estimate NUMERIC(8,2), base_gain_estimate NUMERIC(8,2), bull_gain_estimate NUMERIC(8,2), confidence NUMERIC(5,2) CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 100)), hard_blocker TEXT, evidence_delta_summary TEXT, framework_version TEXT NOT NULL REFERENCES framework_versions(version), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (ipo_id, checkpoint_type, checkpoint_time));
CREATE TABLE research_evidence (evidence_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL REFERENCES ipos(ipo_id) ON DELETE RESTRICT, checkpoint_id BIGINT REFERENCES checkpoints(checkpoint_id) ON DELETE RESTRICT, research_block TEXT NOT NULL CHECK (research_block IN ('R1_BUSINESS','R2_FINANCIALS','R3_VALUATION','R4_PROMOTER_ISSUE','R5_ANALYST','R6_INSTITUTIONAL','R7_DEMAND','R8_ENVIRONMENT')), field_name TEXT NOT NULL, value_text TEXT, numeric_value NUMERIC, source_url TEXT NOT NULL, source_name TEXT, published_at TIMESTAMPTZ, retrieved_at TIMESTAMPTZ NOT NULL DEFAULT now(), verification_status TEXT NOT NULL CHECK (verification_status IN ('VERIFIED','CONFLICT','NOT_VERIFIED')), notes TEXT);
CREATE TABLE subscription_snapshots (snapshot_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL REFERENCES ipos(ipo_id) ON DELETE RESTRICT, captured_at TIMESTAMPTZ NOT NULL, total_x NUMERIC(12,4), qib_x NUMERIC(12,4), nii_x NUMERIC(12,4), retail_x NUMERIC(12,4), anchor_summary TEXT, source_url TEXT NOT NULL, UNIQUE (ipo_id, captured_at, source_url));
CREATE TABLE market_sentiment_snapshots (snapshot_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL REFERENCES ipos(ipo_id) ON DELETE RESTRICT, captured_at TIMESTAMPTZ NOT NULL, gmp_value NUMERIC(14,2), gmp_percent NUMERIC(8,2), gmp_direction TEXT CHECK (gmp_direction IN ('RISING','FALLING','FLAT','UNKNOWN')), source_url TEXT NOT NULL, UNIQUE (ipo_id, captured_at, source_url));
CREATE TABLE listing_outcomes (outcome_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL UNIQUE REFERENCES ipos(ipo_id) ON DELETE RESTRICT, issue_price NUMERIC(14,2) NOT NULL, listing_price NUMERIC(14,2) NOT NULL, listing_gain_percent NUMERIC(8,2) NOT NULL, listing_date DATE NOT NULL, source_url TEXT NOT NULL, verified_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE assessments (assessment_id BIGSERIAL PRIMARY KEY, ipo_id BIGINT NOT NULL UNIQUE REFERENCES ipos(ipo_id) ON DELETE RESTRICT, canonical_checkpoint_id BIGINT NOT NULL REFERENCES checkpoints(checkpoint_id) ON DELETE RESTRICT, outcome_id BIGINT NOT NULL REFERENCES listing_outcomes(outcome_id) ON DELETE RESTRICT, classification TEXT NOT NULL CHECK (classification IN ('STRONG_HIT','MODERATE_HIT','FALSE_POSITIVE','MISSED_OPPORTUNITY','CORRECT_AVOIDANCE')), forecast_error_pp NUMERIC(8,2), is_missed_opportunity BOOLEAN NOT NULL DEFAULT false, missed_signal_summary TEXT, assessed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE learnings (learning_id BIGSERIAL PRIMARY KEY, origin_ipo_id BIGINT REFERENCES ipos(ipo_id) ON DELETE RESTRICT, hypothesis TEXT NOT NULL, observed_signal TEXT NOT NULL, development_result TEXT, validation_result TEXT, status TEXT NOT NULL CHECK (status IN ('TESTING','VALIDATED','ADOPTED','REJECTED')), proposed_change TEXT, adopted_framework_version TEXT REFERENCES framework_versions(version), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE efficacy_snapshots (efficacy_id BIGSERIAL PRIMARY KEY, as_of_date DATE NOT NULL, framework_version TEXT NOT NULL REFERENCES framework_versions(version), universe_count INTEGER NOT NULL DEFAULT 0, recommendation_count INTEGER NOT NULL DEFAULT 0, positive_hit_rate NUMERIC(8,4), twenty_percent_hit_rate NUMERIC(8,4), a_plus_plus_hit_rate NUMERIC(8,4), a_plus_hit_rate NUMERIC(8,4), opportunity_capture_rate NUMERIC(8,4), miss_rate NUMERIC(8,4), false_positive_rate NUMERIC(8,4), correct_avoidance_rate NUMERIC(8,4), avg_recommended_gain NUMERIC(8,2), avg_estimated_gain NUMERIC(8,2), forecast_error NUMERIC(8,2), upgrade_hit_rate NUMERIC(8,4), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (as_of_date, framework_version));
CREATE TABLE run_log (run_id BIGSERIAL PRIMARY KEY, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, run_type TEXT NOT NULL CHECK (run_type IN ('DISCOVERY','REASSESSMENT','FINAL_DAY','LISTING_OUTCOME','LEARNING_EVALUATION','BACKTEST','INTEGRITY_AUDIT','MANUAL')), framework_version TEXT REFERENCES framework_versions(version), discovered_count INTEGER NOT NULL DEFAULT 0, researched_count INTEGER NOT NULL DEFAULT 0, checkpoint_count INTEGER NOT NULL DEFAULT 0, outcomes_added INTEGER NOT NULL DEFAULT 0, errors JSONB, status TEXT NOT NULL DEFAULT 'STARTED' CHECK (status IN ('STARTED','COMPLETED','PARTIAL','FAILED')));
CREATE INDEX idx_ipos_status_dates ON ipos(status, issue_close_date, listing_date);
CREATE INDEX idx_checkpoints_ipo_time ON checkpoints(ipo_id, checkpoint_time DESC);
CREATE INDEX idx_checkpoints_ipo_type ON checkpoints(ipo_id, checkpoint_type);
CREATE INDEX idx_research_evidence_ipo_checkpoint ON research_evidence(ipo_id, checkpoint_id);
CREATE INDEX idx_research_evidence_block ON research_evidence(research_block, verification_status);
CREATE INDEX idx_subscription_ipo_time ON subscription_snapshots(ipo_id, captured_at DESC);
CREATE INDEX idx_sentiment_ipo_time ON market_sentiment_snapshots(ipo_id, captured_at DESC);
CREATE INDEX idx_learnings_status ON learnings(status);
CREATE INDEX idx_run_log_started ON run_log(started_at DESC);
CREATE RULE checkpoints_no_update AS ON UPDATE TO checkpoints DO INSTEAD NOTHING;
CREATE RULE checkpoints_no_delete AS ON DELETE TO checkpoints DO INSTEAD NOTHING;
INSERT INTO framework_versions (version, status, effective_at, scoring_config, rules_config, source_spec_document_url) VALUES ('1.0','FROZEN',now(),'{"business_quality":15,"financial_quality":15,"valuation":20,"institutional_conviction":20,"market_demand":10,"analyst_consensus":10,"sector_ipo_environment":5,"gmp_confirmation":5}'::jsonb,'{"grade_A_plus_plus_min":95,"grade_A_plus_min":90,"grade_A_min":85,"missed_opportunity_threshold_pct":20,"critical_missing_evidence_blocks_high_conviction":true,"actionable_grades":["A++","A+"],"canonical_efficacy_checkpoint":"T2_FINAL_DAY"}'::jsonb,'https://docs.google.com/document/d/1uclQCT35NXz0r95I9mfrqlwrMAsgKrH-k6tsbUupGi4');
